'use strict';
const $=id=>document.getElementById(id),canvas=$('river'),ctx=canvas.getContext('2d');
let mode='idle',paused=false,count=0,elapsed=0,distance=0,speed=0,strokes=[],lastStroke=-1e9,lastDemo=0,stream=null,wake=null,lastTime=performance.now(),lastCapture=0,prev=null,flowTravel=0,extreme=0,direction=0,half=false,lastMove=0;
const sample=document.createElement('canvas');sample.width=96;sample.height=72;const sc=sample.getContext('2d',{willReadFrequently:true});
function say(s){$('status').textContent=s}
function clearDetector(){prev=null;flowTravel=0;extreme=0;direction=0;half=false;lastMove=performance.now()}
function stroke(t=performance.now()){if(mode==='idle'||paused||t-lastStroke<800)return;lastStroke=t;count++;strokes.push(elapsed);speed=Math.min(40,speed+15);$('count').textContent=count;}
async function lock(){try{if('wakeLock'in navigator)wake=await navigator.wakeLock.request('screen')}catch{}}
function stopCamera(){if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;document.body.classList.remove('camera-active');$('video').srcObject=null;$('placeholder').style.display='grid';clearDetector()}
function sync(){ $('pause').disabled=mode==='idle';$('pause').textContent=paused?'Продолжить':'Пауза';$('stroke').disabled=mode!=='demo'||paused;$('modeLabel').textContent=mode==='idle'?'ГОТОВ К ОТПЛЫТИЮ':paused?'ПАУЗА':mode==='demo'?'ДЕМО · АВТОГРЕБКИ':'КАМЕРА · ЭКСПЕРИМЕНТ';$('demo').textContent=mode==='demo'?'Демо запущено':'Посмотреть демо ↗';}
function fresh(){count=0;elapsed=0;distance=0;speed=0;strokes=[];lastStroke=-1e9;lastDemo=0;$('count').textContent='0';clearDetector()}
$('demo').onclick=()=>{stopCamera();fresh();mode='demo';paused=false;sync();lock();say('Демо: лодка гребёт автоматически. Кнопкой «Гребок вручную» можно добавить импульс.');};
$('camera').onclick=async()=>{if(stream){say('Камера уже подключена. Сделай несколько полных гребков.');return}const b=$('camera');b.disabled=true;say('Запрашиваем доступ к камере…');try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('unsupported');stream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:'environment'},width:{ideal:640},height:{ideal:480},frameRate:{ideal:20,max:24}}});$('video').srcObject=stream;await $('video').play();stream.getVideoTracks()[0].onended=()=>{stopCamera();paused=true;sync();say('Камера отключилась. Подключи её снова.')};fresh();mode='camera';paused=false;document.body.classList.add('camera-active');$('placeholder').style.display='none';sync();lock();say('Камера включена. Закрепи iPhone сбоку и сделай 5 полных гребков. Сравни их со счётчиком.');}catch(e){stopCamera();say(e.name==='NotAllowedError'?'Нет доступа к камере. Открой сайт в Safari и разреши камеру в настройках сайта.':e.name==='NotFoundError'?'Камера не найдена. Можно посмотреть демо.':'Не удалось запустить камеру. Открой ссылку в Safari на iPhone и попробуй снова.');}finally{b.disabled=false}};
$('pause').onclick=()=>{paused=!paused;speed=0;clearDetector();sync();if(!paused)lock();say(paused?'Тренировка на паузе.':mode==='camera'?'Продолжаем. Камера считает циклы движения.':'Демо продолжается.');};
$('stroke').onclick=()=>stroke();$('reset').onclick=()=>{stopCamera();fresh();mode='idle';paused=false;wake?.release();sync();say('Новая прогулка. Подключи камеру или запусти демо.');};$('sensitivity').oninput=()=>{$('senseValue').value=$('sensitivity').value;clearDetector()};
$('full').onclick=async()=>{const el=document.querySelector('.game');if(document.fullscreenElement){await document.exitFullscreen();return}if(el.classList.contains('fullscreen')){el.classList.remove('fullscreen');return}try{if(el.requestFullscreen)await el.requestFullscreen();else el.classList.add('fullscreen')}catch{el.classList.add('fullscreen')}};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode!=='idle'){paused=true;speed=0;clearDetector();sync();say('Пауза: приложение было свёрнуто. Нажми «Продолжить», когда вернёшься.')}else lastTime=performance.now()});window.addEventListener('pagehide',()=>{stopCamera();wake?.release()});
// Sparse block matching in the middle of the frame. Counts alternating horizontal
// movement, not exertion or anatomical pose. Confidence rejects flat/static patches.
function flow(t){const v=$('video');if(v.readyState<2)return;sc.drawImage(v,0,0,96,72);const rgba=sc.getImageData(0,0,96,72).data,gray=new Uint8Array(6912);for(let i=0;i<gray.length;i++)gray[i]=(rgba[i*4]*3+rgba[i*4+1]*6+rgba[i*4+2])/10;if(!prev){prev=gray;return}let votes=[];for(let y=16;y<60;y+=10)for(let x=22;x<78;x+=10){let best=1e9,dxBest=0,dyBest=0,zero=0,texture=0;for(let yy=-3;yy<=3;yy+=2)for(let xx=-3;xx<=3;xx+=2){let k=(y+yy)*96+x+xx;zero+=Math.abs(gray[k]-prev[k]);texture+=Math.abs(prev[k]-prev[k+1])}if(texture<75||zero<65)continue;for(let dy=-2;dy<=2;dy++)for(let dx=-5;dx<=5;dx++){let err=0;for(let yy=-3;yy<=3;yy+=2)for(let xx=-3;xx<=3;xx+=2)err+=Math.abs(gray[(y+yy)*96+x+xx]-prev[(y+yy-dy)*96+x+xx-dx]);if(err<best){best=err;dxBest=dx;dyBest=dy}}if(best<zero*.78&&Math.abs(dxBest)>Math.abs(dyBest))votes.push(dxBest)}prev=gray;if(votes.length<3){if(t-lastMove>1800){flowTravel=0;extreme=0;direction=0;half=false}return}votes.sort((a,b)=>a-b);let dx=votes[Math.floor(votes.length/2)];if(!dx)return;lastMove=t;flowTravel+=dx;const threshold=23-Number($('sensitivity').value)*1.7;if(!direction){if(Math.abs(flowTravel)>threshold){direction=Math.sign(flowTravel);extreme=flowTravel}return}if(direction>0){extreme=Math.max(extreme,flowTravel);if(extreme-flowTravel>threshold){direction=-1;extreme=flowTravel;half=true}}else{extreme=Math.min(extreme,flowTravel);if(flowTravel-extreme>threshold){direction=1;extreme=flowTravel;if(half){stroke(t);half=false}}}if(Math.abs(flowTravel)>10000){extreme-=flowTravel;flowTravel=0}}
const hash=n=>{let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)};
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h)}
function center(y){return 240+Math.sin(y/170)*34+Math.sin(y/330)*20}
function tree(x,y,size=1){rect(x-2*size,y+8*size,4*size,9*size,'#514e35');rect(x-9*size,y,18*size,11*size,'#234f40');rect(x-12*size,y-8*size,24*size,12*size,'#30654a');rect(x-8*size,y-16*size,16*size,12*size,'#427851');rect(x-4*size,y-21*size,8*size,10*size,'#5b8b58');rect(x-8*size,y-8*size,4*size,7*size,'#6d975b')}
function draw(t){const offset=distance*.72;rect(0,0,480,300,'#809b5e');for(let y=0;y<300;y+=3){const world=y-offset,c=center(world),width=145+Math.sin(world/120)*12;rect(c-width/2-13,y,width+26,3,'#b2bc7c');rect(c-width/2-6,y,width+12,3,'#d6cc91');rect(c-width/2,y,width,3,'#67aaa3');rect(c-width/2+8,y,width-16,3,'#559b99');rect(c-width/2+20,y,width-40,3,'#4b908f')}
for(let k=Math.floor(-offset/22)-2;k<(300-offset)/22+2;k++){let world=k*22,y=world+offset;let c=center(world);for(let side of [-1,1]){let x=c+side*(100+hash(k*13+side)*105);if(hash(k+side*7)>.22)tree(x,y,.8+hash(k+81)*.5);rect(x+25,y+15,3,2,'#c4c784');rect(x-18,y+7,5,2,'#607e4e')}}
for(let k=Math.floor(-offset/18)-1;k<(300-offset)/18+1;k++){let y=k*18+offset,c=center(k*18),x=c+(hash(k*8)-.5)*100;rect(x,y,8+hash(k)*12,1,'#7cb9ae');rect(x+22,y+6,5,1,'#66aaa2')}
// Small bank-side details repeat with the route, always outside the water.
let dockY=((80+offset)%600+600)%600;let dockX=center(dockY-offset)-95;rect(dockX,dockY,48,12,'#6f6245');for(let i=0;i<6;i++)rect(dockX+i*8,dockY,6,10,'#b59b64');rect(dockX,dockY-4,4,19,'#5e513b');rect(dockX+44,dockY-4,4,19,'#5e513b');
if(count>=85){for(let h=0;h<3;h++){let hx=40+h*32,hy=80+(h%2)*45;rect(hx,hy,25,24,'#d5bb80');rect(hx-3,hy-4,31,7,'#965b45');rect(hx+1,hy-10,23,7,'#b16c4b');rect(hx+8,hy-15,10,6,'#b16c4b');rect(hx+4,hy+5,5,6,'#3c6455');rect(hx+15,hy+10,6,14,'#665541')}}
const by=164,bx=center(by-offset),bob=Math.sin(t/600)*.7,impulse=Math.max(0,1-(t-lastStroke)/800);ctx.save();ctx.translate(Math.round(bx),Math.round(by+bob));for(let i=0;i<3;i++){let spread=7+i*6;rect(-spread,22+i*7,spread*2,1,'#90c9b9')}rect(-8,-20,17,46,'#397d7d');rect(-5,-27,10,5,'#f5dc9a');rect(-8,-22,16,37,'#e8bd72');rect(-5,15,10,7,'#c58a4c');rect(-2,22,4,4,'#c58a4c');rect(-5,-18,10,29,'#906a46');rect(-3,-15,6,7,'#414e40');rect(-4,-2,8,12,'#eb875a');rect(-3,-7,6,6,'#f0c793');rect(-3,-9,6,3,'#f2edcc');let oy=3-impulse*12;ctx.strokeStyle='#e9d49e';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-3,3);ctx.lineTo(-27,oy);ctx.moveTo(3,3);ctx.lineTo(27,oy);ctx.stroke();rect(-31,oy-2,9,4,'#e8c583');rect(23,oy-2,9,4,'#e8c583');ctx.restore();
}
function tick(t){const dt=Math.min((t-lastTime)/1000,.1);lastTime=t;if(mode!=='idle'&&!paused){elapsed+=dt;if(mode==='demo'&&elapsed-lastDemo>2.6){stroke(t);lastDemo=elapsed}if(mode==='camera'&&t-lastCapture>80){flow(t);lastCapture=t}speed*=Math.exp(-dt*.6);distance+=speed*dt}draw(t);$('clock').textContent=String(Math.floor(elapsed/60)).padStart(2,'0')+':'+String(Math.floor(elapsed%60)).padStart(2,'0');strokes=strokes.filter(s=>elapsed-s<30);$('rate').textContent=strokes.length>=2?Math.round((strokes.length-1)*60/Math.max(1,strokes[strokes.length-1]-strokes[0])):'—';let progress=Math.min(count/100,1);$('progress').style.width=progress*100+'%';$('chapter').textContent=count>=100?'02 / РЕЧНАЯ ДЕРЕВНЯ':'01 / ЛЕСНОЙ ПРИЧАЛ';$('journey').textContent=count===0?'Впереди — тихая вода':count<100?`${100-count} гребков до деревни`:'Ты у деревни. Плывём дальше!';requestAnimationFrame(tick)}sync();requestAnimationFrame(tick);
